This is a paint geometry failure; a clean console does not prove the field is usable. Apply the responsive-layout skill by testing the specific contract: **the final address field can scroll fully above the sticky checkout action, and checkout remains tappable.** Leave intentional `Stack` overlaps out of the assertions.

Adapt this test to your fixture and existing scrollable keys:

```dart
testWidgets('checkout does not cover the final address field at 320',
    (tester) async {
  tester.view.devicePixelRatio = 1;
  tester.view.physicalSize = const Size(320, 640);
  addTearDown(tester.view.reset);

  var submitted = false;

  await tester.pumpWidget(
    MaterialApp(
      builder: (context, child) => MediaQuery(
        data: MediaQuery.of(context).copyWith(
          textScaler: TextScaler.linear(2),
        ),
        child: child!,
      ),
      home: CheckoutFixture.longAddress(
        onCheckout: () => submitted = true,
      ),
    ),
  );
  await tester.pumpAndSettle();

  expect(tester.takeException(), isNull);

  final field = find.byKey(const ValueKey('last-address-field'));
  final action = find.byKey(const ValueKey('checkout-action'));
  final viewport = find.byKey(const ValueKey('address-viewport'));

  // Reveal the end using the screen's actual scrolling behavior.
  await tester.drag(
    find.byKey(const ValueKey('address-scroll')),
    const Offset(0, -2000),
  );
  await tester.pumpAndSettle();

  final fieldRect = tester.getRect(field);
  final actionRect = tester.getRect(action);
  final viewportRect = tester.getRect(viewport);

  expect(fieldRect.overlaps(actionRect), isFalse);
  expect(fieldRect.bottom, lessThanOrEqualTo(actionRect.top - 16));
  expect(fieldRect.top, greaterThanOrEqualTo(viewportRect.top));
  expect(fieldRect.bottom, lessThanOrEqualTo(viewportRect.bottom));

  expect(action.hitTestable(), findsOneWidget);
  await tester.tap(action);
  await tester.pumpAndSettle();
  expect(submitted, isTrue);
  expect(tester.takeException(), isNull);
});
```

